-- T13335 (journal spec §1.5 N7 rule 3) — the copy reconcile's pinned HLCs.
--
-- _sync_capture.pin_json: for a capture of a `rebind` frame the copy
-- reconcile wrote under rule 3 (a value the original replica sealed but the
-- stream never saw), the HLCs the sealer must publish unchanged instead of
-- ticking: `{"h"?: hlc, "fh"?: {column: hlc}}`. `h` is the op's own HLC (a
-- delete), `fh` the per-field HLCs (an insert or update). NULL for every
-- other capture. The pin dies with its capture when the capture is sealed.
--
-- Local-only.
--
-- Do not edit this file once applied: its hash is recorded per store.
ALTER TABLE _sync_capture ADD COLUMN pin_json TEXT;
